agent_base_units.command:
cd /app/test/config && cat > fixtures/duration-shard/vitest.config.isolate.ts <<'EOF'
import { defineConfig } from 'vitest/config'
export default defineConfig({
  test: {
    sequence: {
      shardStrategy: 'time',
      isolateSlowThreshold: 200,
      durationHistoryPath: 'duration-history.json',
    },
  },
})
EOF
echo "=== isolate 1/2 ===" && timeout 120 pnpm vitest --run --config /app/test/config/fixtures/duration-shard/vitest.config.isolate.ts --root fixtures/duration-shard --shard=1/2 2>&1 | grep -E "test/[abcd]\.test\.ts" | head
echo "=== isolate 2/2 ===" && timeout 120 pnpm vitest --run --config /app/test/config/fixtures/duration-shard/vitest.config.isolate.ts --root fixtures/duration-shard --shard=2/2 2>&1 | grep -E "test/[abcd]\.test\.ts" | head

